var EXTRA=[{"dot": "gray", "pmid": "43012382", "j": "Sports Health", "h": "Atlete operate di LCA: la forma del piatto tibiale non predice la rottura controlaterale", "v": "Coorte prospettica del Vermont con risonanza del ginocchio sano: nessuna differenza di geometria cartilaginea fra chi si rompe l'altro crociato e chi no; i casi erano pochissimi.", "temi": ["LCA", "ginocchio controlaterale", "piatto tibiale"], "doi": "10.1177/19417381261503150"}, {"dot": "gray", "pmid": "43009893", "j": "BMC Musculoskelet Disord", "h": "Robot cinese HURWA contro protesi manuale: asse più preciso, funzione uguale", "v": "Studio cinese presentato come randomizzato ma registrato a posteriori: allineamento più vicino all'obiettivo con il robot, nessuna differenza di dolore, funzione o soddisfazione a breve; descrive anche la curva di apprendimento.", "temi": ["protesi robotica", "curva di apprendimento", "allineamento"], "doi": "10.1186/s12891-026-09864-0"}, {"dot": "gray", "pmid": "43009638", "j": "Sports Med", "h": "Ricostruzione del LCA tardiva: deficit di flessione nel cammino che persistono", "v": "Meta-analisi di studi caso-controllo sul cammino: chi è operato oltre l'anno dalla lesione mostra deficit sagittali più duraturi; confronti indiretti fra studi diversi, qualità metodologica moderata.", "temi": ["LCA", "tempistica dell'intervento", "cammino"], "doi": "10.1007/s40279-026-02575-5"}, {"dot": "gray", "pmid": "43014557", "j": "J Arthroplasty", "h": "Oppioidi prima della protesi: marcatore di vulnerabilità sociale e di recupero peggiore", "v": "Coorte retrospettiva di Detroit su anca e ginocchio: la prescrizione di oppioidi nel mese prima si associa a più complicanze e meno beneficio riferito; gli autori lo leggono come marcatore di rischio, non come causa.", "temi": ["protesi totale", "oppioidi", "recupero"], "doi": "10.1016/j.arth.2026.11.036"}, {"dot": "gray", "pmid": "43008903", "j": "J Arthroplasty", "h": "Antibiotico dopo la protesi: una dose, ventiquattro ore o profilassi orale prolungata?", "v": "Revisione narrativa del gruppo di Parvizi: le linee guida divergono e manca un modello validato per scegliere chi meriti la profilassi prolungata; nessun dato nuovo.", "temi": ["protesi totale", "infezione periprotesica", "profilassi antibiotica"], "doi": "10.1016/j.arth.2026.11.016"}, {"dot": "gray", "pmid": "43010001", "j": "J Orthop Surg Res", "h": "Pianificazione tridimensionale con intelligenza artificiale e guide su misura nella protesi", "v": "Coorte esplorativa cinese non randomizzata, piccolissima: alcuni punteggi a sei mesi migliori, asse globale non diverso; gli autori stessi leggono i valori di p come nominali.", "temi": ["protesi totale", "intelligenza artificiale", "guide su misura"], "doi": "10.1186/s13018-026-07132-4"}, {"dot": "gray", "pmid": "43009824", "j": "BMC Med Imaging", "h": "Radiomica dell'osso subcondrale alla risonanza per prevedere l'artrosi del ginocchio", "v": "Modelli costruiti sulla coorte OAI con buona discriminazione interna; nessuna validazione esterna, lontani dall'uso clinico.", "temi": ["artrosi", "risonanza magnetica", "radiomica"], "doi": "10.1186/s12880-026-02654-z"}, {"dot": "gray", "pmid": "43012253", "j": "J Back Musculoskelet Rehabil", "h": "Padel in Arabia Saudita: il ginocchio fra le sedi di infortunio, legato alle ore di gioco", "v": "Questionario autoriferito con campionamento a valanga: utile come segnale su uno sport in crescita anche in Ticino, non come stima di incidenza.", "temi": ["padel", "infortuni sportivi", "ginocchio"], "doi": "10.1177/10538127261506062"}, {"dot": "gray", "pmid": "43011758", "j": "Cureus", "h": "Consigli sulla guida dopo protesi scritti nella lettera di dimissione", "v": "Progetto di qualità a Leicester: inserire una sezione standard nel modulo di dimissione rende quasi sistematica l'informazione sulla ripresa della guida; contesto britannico, due cicli brevi.", "temi": ["protesi totale", "ripresa della guida", "dimissione"], "doi": "10.7759/cureus.118977"}];
var SCOPERTE=[{"pmid": "43011836", "t": "Cina: Tai Chi e Baduanjin contro l'educazione sanitaria nell'artrosi del ginocchio, un RCT a tre bracci", "v": "Da Zhongshan, due ginnastiche tradizionali cinesi confrontate per sorteggio con la sola educazione: entrambe riducono il dolore WOMAC rispetto al controllo per quasi un anno, senza differenze fra loro. Vale come finestra su un modo diverso di prescrivere l'esercizio, con il limite di un controllo non attivo.", "temi": ["artrosi", "Cina", "esercizio terapeutico"], "doi": "10.2147/JPR.S649293"}, {"pmid": "43013921", "t": "Vietnam: prelievo del tendine rotuleo con due piccole incisioni e una guida di taglio a basso profilo", "v": "Dall'ospedale militare 108 di Hanoi, una tecnica con video per standardizzare la larghezza dell'innesto e proteggere il paratenonio. Non è il tuo innesto, ma è un esempio di come la chirurgia vietnamita stia pubblicando tecnica propria su J ISAKOS.", "temi": ["LCA", "Vietnam", "prelievo dell'innesto"], "doi": "10.1016/j.jisako.2026.101238"}, {"pmid": "43013808", "t": "Londra e Shanghai: dalla scansione tridimensionale della pianta del piede all'asse del ginocchio con l'apprendimento profondo", "v": "Un modello che legge la forma della pianta del piede e stima arco, retropiede e asse frontale del ginocchio, con mappe che mostrano quali regioni pesano. Validazione solo interna su un campione piccolo: interessa come idea di screening senza raggi, non come strumento.", "temi": ["intelligenza artificiale", "asse dell'arto", "screening"], "doi": "10.1371/journal.pdig.0001802"}];
var SOC={"2": {"video": "Trombosi dopo protesi d'anca o di ginocchio: il trial PEPPER, oltre quindicimila pazienti.\n\nMorte o trombosi sintomatica a sei mesi: 1,26% con aspirina, 0,94% con rivaroxaban; l'aspirina non si dimostra non inferiore. In compenso, sanguinamenti e problemi di ferita leggermente meno frequenti con l'aspirina.\n\nIl limite: nessun farmaco vince davvero, e i dati del solo ginocchio non sono nel riassunto. La scelta resta individuale.\nFonte: PubMed, PMID 43013818.", "linkedin": "Profilassi tromboembolica dopo protesi: il trial PEPPER (N Engl J Med, 2026).\n\n18.883 randomizzati, 15.317 per protocollo (8.103 ginocchia). Aspirina 81 mg × 2, warfarin INR 2,0, rivaroxaban 10 mg per 30 giorni. Morte o TEV sintomatico a 6 mesi 1,26%, 1,23%, 0,94%; aspirina contro rivaroxaban +0,30 punti (IC 95% da −0,20 a 0,81), oltre il margine di 0,69.\n\nIl limite: nessun braccio superiore, sicurezza a favore dell'aspirina senza significatività, ginocchio non separato nell'abstract.\nFonte: PubMed, PMID 43013818.", "instagram": "Dopo una protesi si previene la trombosi per un mese.\n\nUn grande studio su più di 15.000 persone: con l'aspirina le complicazioni sono state l'1,26%, con un anticoagulante lo 0,94%. Con l'aspirina un po' meno sanguinamenti.\n\nNessun farmaco è risultato nettamente migliore. PMID 43013818.", "pazienti": "Protesi di ginocchio: come si prevengono i trombi?\n\nDopo una protesi si prende per circa un mese un farmaco contro i trombi. Un grande studio americano ha confrontato l'aspirina con due anticoagulanti in più di 15.000 persone: le complicazioni sono state rare in tutti i gruppi, poco più di una persona su cento.\n\nIl limite: nessun farmaco è risultato chiaramente il migliore; la scelta dipende dalla storia di ciascuno ed è del chirurgo, insieme al paziente.\nFonte: PubMed, PMID 43013818."}};
var SOCV={"2": {"video": {"chir": ["Trial PEPPER, New England Journal of Medicine 2026. Disegno pragmatico di non inferiorità, tre bracci per trenta giorni dopo protesi elettiva d'anca o di ginocchio: aspirina ottantuno milligrammi due volte al giorno, warfarin con INR bersaglio due, rivaroxaban dieci milligrammi al giorno. Diciottomilaottocentottantatré randomizzati, quindicimilatrecentodiciassette nell'analisi per protocollo, di cui ottomilacentotré ginocchia. Esito di efficacia a sei mesi, valutato in cieco: morte per qualsiasi causa o tromboembolismo venoso sintomatico.", "Risultati. Efficacia: uno virgola ventisei per cento con aspirina, uno virgola ventitré con warfarin, zero virgola novantaquattro con rivaroxaban. Aspirina contro rivaroxaban: più zero virgola trenta punti, intervallo di confidenza da meno zero virgola venti a più zero virgola ottantuno. Il margine era zero virgola sessantanove: il limite superiore lo supera, quindi la non inferiorità dell'aspirina non è dimostrata. Lo stesso contro warfarin. Sulla sicurezza, sanguinamenti, reinterventi di ferita e infarti, l'aspirina va meglio di circa zero virgola sette punti, ma gli intervalli toccano lo zero.", "Che cosa significa. Non è una vittoria del rivaroxaban: nessun braccio è dimostrato superiore. È uno scambio fra circa tre eventi trombotici in più ogni mille pazienti con l'aspirina e circa sette eventi di sicurezza in meno, con incertezza su entrambi. I limiti: analisi primaria per protocollo, bracci di numerosità diversa, dose di aspirina americana, e i risultati del solo ginocchio non sono nel riassunto. Per chi usa un anticoagulante, nessun motivo di cambiare; per chi usa aspirina nel basso rischio, una scelta difendibile ma non più rassicurante di prima. Fonte: PubMed, PMID 43013818."], "misto": ["Dopo una protesi d'anca o di ginocchio, per circa un mese si dà un farmaco per prevenire i trombi nelle vene delle gambe. Quale farmaco usare è una domanda aperta da anni. Il trial americano PEPPER, pubblicato sul New England Journal of Medicine, ha assegnato per sorteggio più di diciottomila pazienti a tre scelte: aspirina a basso dosaggio, warfarin oppure rivaroxaban, un anticoagulante in compresse.", "A sei mesi, morte o trombosi con sintomi si sono verificate nell'uno virgola ventisei per cento dei pazienti con aspirina e nello zero virgola novantaquattro per cento con rivaroxaban. La differenza è piccola, ma lo studio non riesce a dimostrare che l'aspirina sia equivalente. Al contrario, con l'aspirina sanguinamenti, problemi della ferita e infarti sono stati un po' meno frequenti, anche se la differenza non è certa.", "Che cosa ne ricaviamo, come medici curanti e fisioterapisti? Che nessun farmaco vince in modo netto: si scambia un piccolo vantaggio contro i trombi con un piccolo svantaggio sui sanguinamenti. La scelta va fatta sul singolo paziente, guardando la sua storia di trombosi, di sanguinamenti e gli altri farmaci che prende. I limiti: i risultati del solo ginocchio non sono riportati nel riassunto, e la dose di aspirina è quella americana. Fonte: PubMed, PMID 43013818."], "pazienti": ["Dopo una protesi di ginocchio o d'anca, per circa un mese si prende un farmaco che aiuta a evitare i trombi, cioè coaguli di sangue nelle vene delle gambe. Esistono più farmaci possibili: l'aspirina a basso dosaggio e alcuni anticoagulanti. Un grande studio americano ha voluto capire se l'aspirina protegga quanto gli altri.", "Più di quindicimila persone sono state seguite per sei mesi. Le complicazioni gravi sono state rare in tutti i gruppi: poco più di una persona su cento con l'aspirina, un po' meno di una su cento con l'anticoagulante. Con l'aspirina, però, si sono avuti un po' meno sanguinamenti e problemi della ferita. Nessun farmaco è risultato chiaramente il migliore in tutto.", "Che cosa vuol dire per chi deve operarsi? Che tutti e tre i farmaci proteggono, e che la scelta dipende dalla storia di ciascuno: trombosi passate, rischio di sanguinare, altri farmaci in corso. È importante prendere il farmaco indicato per tutto il periodo previsto e muoversi presto dopo l'intervento. Il limite dello studio: i dati del solo ginocchio non sono ancora riportati nel riassunto. Per il proprio caso decide il chirurgo. Fonte: PubMed, PMID 43013818."]}, "linkedin": {"chir": ["Profilassi tromboembolica dopo protesi: trial PEPPER (N Engl J Med, 2026)", "RCT pragmatico di non inferiorità, 18.883 randomizzati, 15.317 per protocollo (7.214 anche, 8.103 ginocchia). Aspirina 81 mg × 2, warfarin INR 2,0, rivaroxaban 10 mg per 30 giorni. Morte o TEV sintomatico a 6 mesi: 1,26%, 1,23%, 0,94%. Aspirina contro rivaroxaban +0,30 punti (IC 95% da −0,20 a 0,81) e contro warfarin +0,23 (da −0,34 a 0,81): oltre il margine di 0,69. Sicurezza 2,91%, 3,36%, 3,48%; rivaroxaban contro aspirina +0,68 (da −0,04 a 1,41).", "Il limite: nessun braccio superiore, è uno scambio fra eventi trombotici e di sicurezza; ginocchio non separato nell'abstract; dose di aspirina americana.\nFonte: PubMed, PMID 43013818."], "misto": ["Trombosi dopo protesi: il più grande studio randomizzato non promuove l'aspirina da sola", "Il trial PEPPER ha confrontato per sorteggio aspirina a basso dosaggio, warfarin e rivaroxaban per un mese dopo protesi d'anca o di ginocchio, in più di 15.000 pazienti. Morte o trombosi con sintomi a sei mesi: 1,26% con aspirina, 1,23% con warfarin, 0,94% con rivaroxaban; lo studio non riesce a dimostrare che l'aspirina sia equivalente. Sanguinamenti e problemi della ferita sono stati un po' meno frequenti con l'aspirina (2,91% contro 3,48% con rivaroxaban), senza certezza statistica.", "Il limite: nessun farmaco vince in modo netto; i risultati del solo ginocchio non sono nel riassunto. La scelta resta individuale.\nFonte: PubMed, PMID 43013818."], "pazienti": ["Dopo la protesi: tre farmaci contro i trombi a confronto", "Un grande studio americano su più di 15.000 persone operate di protesi d'anca o di ginocchio ha confrontato l'aspirina con due anticoagulanti, presi per un mese. Le complicazioni gravi sono state rare con tutti: poco più di una persona su cento con l'aspirina, un po' meno con un anticoagulante, mentre l'aspirina ha dato un po' meno sanguinamenti.", "Nessun farmaco è risultato chiaramente il migliore: la scelta si fa con il chirurgo.\nFonte: PubMed, PMID 43013818."]}, "instagram": {"chir": ["PEPPER, NEJM 2026: profilassi dopo protesi.", "Morte o TEV a 6 mesi: aspirina 1,26%, rivaroxaban 0,94%; differenza +0,30 punti (IC 95% da −0,20 a 0,81), non inferiorità non dimostrata.", "Sicurezza a favore dell'aspirina, senza significatività. PMID 43013818."], "misto": ["Trombosi dopo protesi: aspirina o anticoagulante?", "Uno studio su più di 15.000 pazienti: complicazioni 1,26% con aspirina e 0,94% con rivaroxaban; con l'aspirina un po' meno sanguinamenti.", "Nessun farmaco vince in modo netto. PMID 43013818."], "pazienti": ["Dopo la protesi, un mese di farmaco contro i trombi.", "Un grande studio: complicazioni rare con tutti i farmaci confrontati, poco più di una persona su cento.", "La scelta si fa con il chirurgo. PMID 43013818."]}, "reel": {"chir": ["PEPPER: aspirina dopo protesi.", "Non inferiorità non dimostrata.", "Sicurezza: aspirina meglio, non significativo."], "misto": ["Trombosi dopo protesi.", "Tre farmaci, oltre 15.000 pazienti.", "Nessuno vince in modo netto."], "pazienti": ["Dopo la protesi, i trombi.", "Tutti i farmaci proteggono.", "La scelta è col chirurgo."]}}};
var TAGS={"2": {"linkedin": "#Ortopedia #ProtesiDiGinocchio #Trombosi", "instagram": "#ortopedia #ginocchio #protesidiginocchio #trombosi #prevenzione #aspirina #medicinabasatasulleprove #chirurgiadelginocchio #ortopediaticino #ticino", "kw": "trombosi dopo protesi di ginocchio, aspirina dopo protesi, anticoagulante dopo protesi, prevenzione trombosi, ticino"}};
var NLB={"1": {"prof": ["LCA pediatrico: artrofibrosi 7% con quadricipite contro 0% con ischiocrurali, LET esclusa", "Studio retrospettivo comparativo di livello III (J Pediatr Orthop, 2026; Johns Hopkins; solo abstract): 154 ricostruzioni sotto i 18 anni, 70 con quadricipite e 84 con ischiocrurali. Artrofibrosi 7% contro 0% (p = 0,018); chi la sviluppa è rioperato nel 100% contro il 14% (p < 0,001). Nel gruppo quadricipite più lesioni condrali (39% contro 20%, p = 0,020).", "Nota critica: cinque eventi in tutto, quindi il rischio relativo resta indeterminato (IC 95% da 0,74 a 234 con potenza.py); innesto scelto dal chirurgo e LET esclusa, la combinazione quadricipite più LET non è rappresentata."], "mix": ["Crociato anteriore nei ragazzi: con il tendine quadricipitale più casi di ginocchio rigido", "Uno studio americano su 154 ragazzi operati di crociato anteriore ha confrontato due tendini usati come innesto: con il tendine del quadricipite il ginocchio è diventato rigido nel 7% dei casi, con i tendini della parte posteriore della coscia in nessuno. Chi ha sviluppato la rigidità ha avuto bisogno di un secondo intervento.", "Nota sul limite: i casi di rigidità sono stati cinque, troppo pochi per misurare con precisione la differenza, e il tendine veniva scelto dal chirurgo in ginocchi diversi fra loro."], "paz": ["Ragazzi operati al crociato: un ginocchio rigido dopo l'intervento è raro ma va riconosciuto presto", "Uno studio americano su 154 ragazzi operati di crociato anteriore ha visto che in pochi casi il ginocchio diventa rigido nei mesi dopo l'intervento, più spesso con un tipo di tendine che con un altro. Quando succede, un secondo intervento in genere lo risolve.", "Nota rassicurante: la rigidità è rara e si controlla nelle visite dopo l'intervento; la scelta del tendine si fa con il chirurgo, caso per caso."], "kw": "crociato anteriore ragazzi, ginocchio rigido dopo intervento, tendine quadricipitale, artrofibrosi"}, "2": {"prof": ["Profilassi tromboembolica dopo protesi: nel trial PEPPER l'aspirina non è non inferiore a rivaroxaban", "RCT pragmatico di non inferiorità (N Engl J Med, 2026; 18.883 randomizzati, 15.317 per protocollo, 8.103 ginocchia; solo abstract). Morte o tromboembolismo sintomatico a 6 mesi 1,26% aspirina, 1,23% warfarin, 0,94% rivaroxaban; aspirina contro rivaroxaban +0,30 punti (IC 95% da −0,20 a 0,81) oltre il margine di 0,69. Sicurezza 2,91%, 3,36%, 3,48%: rivaroxaban contro aspirina +0,68 punti (da −0,04 a 1,41).", "Nota critica: nessun braccio è superiore, il trial misura uno scambio fra eventi trombotici ed eventi di sicurezza; risultati separati per il ginocchio non nell'abstract e dose di aspirina americana."], "mix": ["Prevenire i trombi dopo la protesi: un grande studio americano non promuove l'aspirina da sola", "Uno studio su più di 15.000 persone operate di protesi d'anca o di ginocchio ha confrontato per sorteggio tre farmaci per prevenire i trombi per un mese. Con l'aspirina morte o trombosi a sei mesi sono state l'1,26%, con il rivaroxaban lo 0,94%; la differenza è piccola e lo studio non riesce a dire che l'aspirina sia equivalente. Con l'aspirina, però, i sanguinamenti e i problemi della ferita erano un po' meno frequenti.", "Nota sul limite: nessun farmaco è risultato chiaramente migliore degli altri; la scelta resta un equilibrio fra rischio di trombosi e di sanguinamento, valutato per ogni paziente."], "paz": ["Dopo la protesi di ginocchio: come si previene la trombosi", "Dopo una protesi si danno farmaci per un mese per evitare i trombi nelle vene. Un grande studio americano ha confrontato l'aspirina con due anticoagulanti: in tutti i gruppi le complicazioni sono state rare, poco più di una persona su cento.", "Nota rassicurante: tutti e tre i farmaci proteggono; quale usare dipende dalla storia di ciascuno, e lo decide il chirurgo insieme al paziente."], "kw": "trombosi dopo protesi ginocchio, aspirina o anticoagulante, prevenzione trombosi protesi, protesi di ginocchio"}, "3": {"prof": ["Centralizzazione meniscale: editoriale KSSTA sul dubbio fra causa e conseguenza dell'estrusione", "Editoriale (KSSTA, 2026; Dzidzishvili, Ostojic, Chahla, LaPrade): la centralizzazione riduce l'estrusione e migliora la meccanica di contatto, ma molti pazienti con artrosi preesistente ed estrusione persistente dopo riparazione della radice mediale stanno bene nonostante la progressione radiografica. Ipotesi: nel ginocchio degenerativo l'estrusione è più manifestazione che motore dell'artrosi.", "Nota critica: opinione senza dati nuovi, firmata da autori del consensus Delphi favorevole alla centralizzazione; vale come domanda di ricerca, non come indicazione."], "mix": ["Menisco che scivola fuori dal ginocchio: va sempre rimesso al suo posto?", "Quando la radice del menisco si rompe, il menisco tende a scivolare verso l'esterno. Alcuni chirurghi lo fissano anche più al centro con una tecnica detta centralizzazione. Quattro esperti, tra cui alcuni sostenitori di questa tecnica, osservano che molti pazienti stanno bene anche se il menisco resta un po' fuori, e si chiedono se lo scivolamento sia la causa dell'usura o un suo segno.", "Nota sul limite: è un commento di esperti, non uno studio; la domanda resta aperta."], "paz": ["Rottura della radice del menisco: perché non tutto ciò che si vede alla risonanza va corretto", "Dopo la riparazione della radice del menisco, a volte il menisco resta un po' spostato alla risonanza. Alcuni esperti fanno notare che molte persone stanno comunque bene, e che quel piccolo spostamento potrebbe dipendere dall'usura già presente.", "Nota rassicurante: il risultato si giudica sui sintomi e sulla funzione, non solo sull'immagine; ne parla il chirurgo alla visita di controllo."], "kw": "radice del menisco, menisco estruso, riparazione menisco, centralizzazione menisco"}, "4": {"prof": ["Strumenti cannulati e infezioni dopo artroscopia: revisione sistematica di Lubowitz su Arthroscopy", "Revisione sistematica (Arthroscopy, 2026; solo abstract): 14 lavori, 6 di laboratorio e 8 serie cliniche di cluster infettivi, di cui 6 dopo ricostruzione del LCA e 1 dopo sutura meniscale inside-out. Il lume degli strumenti cannulati trattiene spesso batteri, lieviti, muffe e proteine dopo lavaggio e autoclave standard; numeri di infezioni non riportati nell'abstract.", "Nota critica: serie raccolte attorno a cluster, senza denominatore; dimostrano un meccanismo possibile, non un'incidenza."], "mix": ["Infezioni dopo artroscopia: il punto debole può essere la pulizia degli strumenti cavi", "Una revisione della letteratura ha raccolto 14 lavori sugli strumenti chirurgici con un canale interno, usati per esempio nella ricostruzione del crociato. Negli esperimenti di laboratorio il canale resta spesso contaminato anche dopo la sterilizzazione abituale, e otto descrizioni di gruppi di infezioni in ospedali diversi sono state collegate proprio a questi strumenti.", "Nota sul limite: si tratta di casi raccolti dopo che le infezioni si erano già verificate; non si sa quanto spesso accada."], "paz": ["Artroscopia di ginocchio e infezioni: perché la sterilizzazione degli strumenti conta", "Le infezioni dopo un'artroscopia di ginocchio sono rare. Una revisione della letteratura ricorda che gli strumenti con un canale interno richiedono una pulizia particolarmente accurata prima della sterilizzazione.", "Nota rassicurante: è un aspetto controllato dai servizi di sterilizzazione degli ospedali, con protocolli dedicati."], "kw": "infezione dopo artroscopia, sterilizzazione strumenti chirurgici, crociato anteriore infezione, artroscopia ginocchio"}, "5": {"prof": ["Protesi totale: infiltrazione locale contro blocco femorale, stesso dolore e più flessione in seconda giornata", "Meta-analisi di 11 RCT (Acta Ortop Bras, 2026; 1.109 pazienti; con Camilo Helito; solo abstract): dolore precoce MD 0,25 (IC 95% da −0,19 a 0,69), oppioidi MD 0,55 mg (da −3,28 a 4,38); flessione in seconda giornata a favore della LIA di 6,15° (da 3,14 a 9,16), degenza più breve di 0,23 giorni (da 0,06 a 0,41).", "Nota critica: il comparatore è il blocco femorale, oggi spesso sostituito dal blocco degli adduttori; rischio di bias e certezza non nell'abstract."], "mix": ["Dolore dopo protesi di ginocchio: due tecniche di anestesia locale a confronto", "Una revisione di 11 studi con sorteggio, su 1.109 persone operate di protesi di ginocchio, ha confrontato l'anestesia di un nervo della coscia con l'infiltrazione di anestetico direttamente attorno al ginocchio. Il dolore e il bisogno di farmaci forti sono stati simili; con l'infiltrazione il ginocchio si piegava di circa 6 gradi in più al secondo giorno e la degenza era un po' più breve.", "Nota sul limite: le differenze sono piccole, e oggi molti ospedali usano già una terza tecnica che risparmia la forza della coscia."], "paz": ["Protesi di ginocchio: come si controlla il dolore nei primi giorni", "Dopo una protesi di ginocchio il dolore si controlla con più tecniche insieme, tra cui l'anestetico iniettato attorno al ginocchio. Una revisione di molti studi conferma che questa tecnica controlla il dolore e aiuta a muovere il ginocchio presto.", "Nota rassicurante: il piano contro il dolore viene deciso prima dell'intervento con il chirurgo e l'anestesista."], "kw": "dolore dopo protesi ginocchio, anestesia protesi ginocchio, infiltrazione locale, recupero dopo protesi"}, "6": {"prof": ["Cinque percorsi di protesi totale: FJS-12 diverso, ma la filosofia di allineamento non si separa dal chirurgo", "Coorte retrospettiva (J Arthroplasty, 2026; UC Davis; 1.239 protesi; solo abstract): FJS-12 corretto da 39,7 a 58,0 (p = 0,004); cinematico ristretto robotico contro meccanico navigato bilanciato +18,2 punti (IC 95% 8,4-28,1; p = 0,003); PASS 72,8-82,9% (p = 0,902); PROMIS e VR-12 senza differenze.", "Nota critica: ogni percorso coincide con un chirurgo, un impianto e una piattaforma, e mancano le covariate demografiche; gli autori stessi escludono di poter attribuire la differenza all'allineamento."], "mix": ["Protesi di ginocchio con il robot: il chirurgo pesa quanto la tecnica", "Uno studio americano su 1.239 protesi di ginocchio ha confrontato cinque modi di eseguirle, con navigatore o con robot e con filosofie diverse di allineamento. A un anno, la sensazione di «dimenticarsi» della protesi variava fra i gruppi, ma ogni gruppo era operato da un solo chirurgo, e la quota di pazienti soddisfatti era simile in tutti.", "Nota sul limite: non si può sapere se la differenza venga dalla tecnica o dalla mano del chirurgo, come ammettono gli autori."], "paz": ["Protesi di ginocchio: quanto conta la tecnica e quanto il chirurgo", "Uno studio su più di mille protesi di ginocchio ha confrontato modi diversi di eseguire l'intervento, con navigatore o con robot. In tutti i gruppi la grande maggioranza dei pazienti ha raggiunto un risultato giudicato soddisfacente.", "Nota rassicurante: esistono più tecniche valide; quella adatta al proprio ginocchio si sceglie con il chirurgo."], "kw": "protesi ginocchio robotica, allineamento protesi ginocchio, risultati protesi ginocchio, chirurgia robotica ginocchio"}, "7": {"prof": ["Monocompartimentale robotica: salute mentale preoperatoria e soddisfazione, differenza a 6 mesi ma non a 2 anni", "Registro prospettico (Arthroplasty, 2026; Singapore General Hospital; 121 di 241 a dati completi; solo abstract): soddisfazione a 6 mesi 82,4% contro 97,1% (p = 0,008) con MCS < 50, nessuna differenza a 2 anni; KSFS, KSKS e OKS migliorati in modo simile; SF-36 fisico Δ 17,0 contro 11,1 (p = 0,006).", "Nota critica: metà della coorte fuori dall'analisi a dati completi e soglia MCS derivata internamente; l'assenza di differenza a 2 anni con 51 contro 70 pazienti non è equivalenza."], "mix": ["Protesi parziale di ginocchio: l'umore prima dell'intervento pesa sui primi mesi", "In uno studio di Singapore su 121 persone operate di protesi parziale di ginocchio con il robot, chi partiva con un benessere psicologico più basso era meno soddisfatto a sei mesi (82% contro 97%). A due anni la differenza spariva, e il ginocchio migliorava allo stesso modo nei due gruppi.", "Nota sul limite: metà degli operati non aveva tutti i questionari e non è entrata nell'analisi, il che può aver spostato i risultati."], "paz": ["Protesi parziale di ginocchio: i primi mesi possono essere più faticosi del previsto", "Uno studio di Singapore ha visto che chi arriva all'intervento in un periodo di stanchezza o di tristezza può essere meno contento nei primi mesi, ma a due anni il risultato è simile a quello degli altri.", "Nota rassicurante: parlarne prima con il chirurgo aiuta a prepararsi a un recupero che richiede tempo."], "kw": "protesi parziale ginocchio, protesi monocompartimentale, recupero dopo protesi, soddisfazione dopo protesi"}, "8": {"prof": ["Registro canadese: protesi totale non cementata dall'8,4% al 18,6% in cinque anni", "Studio di registro (J Arthroplasty, 2026; Canadian Joint Replacement Registry; 218.229 protesi primarie 2019-2023; solo abstract): quota non cementata 14,3% complessiva; oltre il 90% delle non cementate con un unico sistema d'impianto; uomini OR 1,59 (IC 95% 1,55-1,63).", "Nota critica: nessun esito di sopravvivenza o revisione; descrive l'adozione, non il beneficio."], "mix": ["Protesi di ginocchio senza cemento: in Canada si usano sempre di più", "Il registro nazionale canadese, con 218.229 protesi di ginocchio, mostra che quelle fissate all'osso senza cemento sono passate dall'8,4% al 18,6% dal 2019 al 2023, soprattutto negli uomini e nei più giovani. Quasi tutte usavano lo stesso modello.", "Nota sul limite: il registro dice quanto si usano, non se durano di più o di meno di quelle cementate."], "paz": ["Protesi di ginocchio con o senza cemento: due modi di fissarla all'osso", "Una protesi di ginocchio può essere fissata all'osso con un cemento apposito o senza, lasciando che l'osso cresca sulla sua superficie. In Canada la seconda scelta è sempre più diffusa.", "Nota rassicurante: entrambe le fissazioni sono in uso da anni; quale sia adatta si valuta con il chirurgo."], "kw": "protesi ginocchio senza cemento, protesi ginocchio cementata, registro protesi, protesi totale ginocchio"}};
var ARTICLES=[{n:1,mono:'m-gray',dot:'orange',sec:'res',j:'J Pediatr Orthop',h:'LCA nell\'adolescente: con il quadricipite più artrofibrosi che con gli ischiocrurali (7% contro 0%)',v:'Studio retrospettivo comparativo (Johns Hopkins, 2015-2024): 154 ricostruzioni sotto i 18 anni, 70 con quadricipite e 84 con ischiocrurali, LET esclusa. Artrofibrosi 7% contro 0% (p = 0,018); chi la sviluppa viene rioperato nel 100% dei casi contro il 14%.',ax:'Thai, Rauf, Le, Elsabbagh, ElNemer, Park, Goersch, Lee; Johns Hopkins, Baltimora',date:'nov 2026',meta:'retrospettivo comparativo, 154 pazienti, livello basso, solo abstract',pmid:'43012652',doi:'10.1097/BPO.0000000000003532',journal:'Journal of pediatric orthopedics',authors:'Sydney Thai, Raisa Rauf, Ysa Le, Zaid Elsabbagh, William ElNemer, Kyung Park, Christopher Goersch, R Jay Lee',design:'Studio retrospettivo comparativo di livello III, un centro, giugno 2015-giugno 2024. Esclusi lesioni legamentose associate, LCA già operato, tenodesi extra-articolare laterale, procedure condrali e controllo inferiore a 5 mesi. Artrofibrosi definita come perdita di almeno 10° di estensione, di almeno 20° di flessione, o sintomi meccanici.',pop:'154 pazienti, età 15,1 ± 1,8 anni, femmine 46%: 70 con tendine quadricipitale e 84 con ischiocrurali. Tecnica di prelievo (a tutto spessore o superficiale, con o senza bratta ossea): non riportata nell\'abstract.',results:'Artrofibrosi 7% con quadricipite contro 0% con ischiocrurali (p = 0,018). Nel gruppo quadricipite più lesioni condrali (39% contro 20%, p = 0,020) e diametro maggiore (8,8 ± 0,8 contro 8,1 ± 0,8 mm, p < 0,001); tempo operatorio 142 ± 35 contro 161 ± 35 min (ischiocrurali più lunghi, p < 0,001). Con artrofibrosi: reintervento 100% contro 14% (p < 0,001).',concl:'Gli autori: nel LCA pediatrico il quadricipite si associa a più artrofibrosi e rigidità degli ischiocrurali; la scelta dell\'innesto va adattata al paziente, comprese lesioni condrali e lassità di base.',limits:'Cinque eventi in tutto: stima instabile, rischio relativo non calcolabile con precisione · Innesto scelto dal chirurgo, con più lesioni condrali nel gruppo quadricipite: confondimento per indicazione · LET esclusa, quindi la tua combinazione non è rappresentata',perte:'Arancione: mette in discussione il tuo innesto di default proprio nell\'adolescente, e il 4 novembre l\'UCLA attribuiva la rigidità alla LET e non all\'innesto. Due coorti piccole puntano in direzioni diverse. Cosa fare: sotto i 18 anni con quadricipite più LET, controllo dell\'estensione a 4-6 settimane, non solo a tre mesi.'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'N Engl J Med',h:'Profilassi dopo protesi: l\'aspirina non si dimostra non inferiore a rivaroxaban e warfarin (PEPPER)',v:'Trial randomizzato pragmatico di non inferiorità, 18.883 randomizzati, 15.317 nell\'analisi per protocollo (8.103 protesi di ginocchio). Morte o tromboembolismo sintomatico a 6 mesi: 1,26% aspirina, 1,23% warfarin, 0,94% rivaroxaban; aspirina contro rivaroxaban +0,30 punti (IC 95% da −0,20 a 0,81), oltre il margine di 0,69. Sicurezza a favore dell\'aspirina, senza significatività.',ax:'Pellegrini, Lambourne, Magder … Goldhaber, Maloney … Francis; PEPPER, Stati Uniti',date:'nov 2026',meta:'RCT multicentrico, 18.883 pazienti, livello alto, solo abstract',pmid:'43013818',doi:'10.1056/NEJMoa2602435',journal:'The New England journal of medicine',authors:'Vincent D Pellegrini, Carol A Lambourne, Laurence S Magder, Patricia D Franklin, Jay S Magaziner, Brook I Martin, Richard Iorio, Kevin L Garvin, Michael A Mont, Wayne E Moschetti, Antonia F Chen, David Warwick e altri (gruppo PEPPER)',design:'Trial randomizzato di efficacia comparativa e non inferiorità (PEPPER, NCT02810704), multicentrico, finanziato da PCORI. Tre bracci per 30 giorni: aspirina 81 mg due volte al giorno, warfarin con INR bersaglio 2,0, rivaroxaban 10 mg al giorno. Esiti valutati in cieco a 6 mesi: efficacia = morte per qualsiasi causa o tromboembolismo venoso sintomatico; sicurezza = sanguinamento, reintervento per problemi della ferita o infarto. Margine di non inferiorità 0,69 punti percentuali.',pop:'18.883 randomizzati per protesi elettiva d\'anca o di ginocchio; 15.317 nell\'analisi per protocollo, 7.214 anche e 8.103 ginocchia. Età, comorbilità e risultati separati per il ginocchio: non riportati nell\'abstract.',results:'Efficacia: 77/6.090 (1,26%) aspirina, 52/4.231 (1,23%) warfarin, 47/4.996 (0,94%) rivaroxaban. Aspirina contro rivaroxaban +0,30 punti (IC 95% da −0,20 a 0,81); aspirina contro warfarin +0,23 (da −0,34 a 0,81): limite superiore oltre 0,69, non inferiorità non dimostrata. Sicurezza: 2,91%, 3,36%, 3,48%; rivaroxaban contro aspirina +0,68 punti (da −0,04 a 1,41), warfarin contro aspirina +0,77 (da −0,04 a 1,58). Analisi per intenzione di trattare simile.',concl:'Gli autori: l\'aspirina non è risultata non inferiore a rivaroxaban o warfarin per morte o tromboembolismo sintomatico; warfarin e rivaroxaban non sono risultati non inferiori all\'aspirina per la sicurezza.',limits:'Nessun braccio è risultato superiore: il risultato è uno scambio fra circa 0,3 punti di eventi trombotici e circa 0,7 punti di eventi di sicurezza, entrambi con intervalli che toccano lo zero · Bracci di numerosità diversa e analisi primaria per protocollo · Dose di aspirina americana (81 mg × 2) e nessun dato separato per il ginocchio nell\'abstract',perte:'Verde: tocca ogni tua protesi totale e monocompartimentale. Il trial più grande mai fatto non dice che l\'aspirina basti: non la promuove a scelta di default, e non dimostra nemmeno che rivaroxaban sia superiore. Cosa fare: nessun cambio se usi già un anticoagulante; se usi aspirina nel paziente a basso rischio, la scelta resta difendibile ma con un margine trombotico non escluso.'},
{n:3,mono:'m-kssta',dot:'green',sec:'res',j:'KSSTA',h:'Centralizzazione del menisco: l\'estrusione è causa dell\'artrosi o sua conseguenza?',v:'Editoriale (Dzidzishvili, Ostojic, Chahla, LaPrade): molti pazienti con estrusione residua dopo riparazione della radice mediale stanno bene nonostante la progressione radiografica; l\'estrusione potrebbe essere un segno dell\'artrosi più che il suo motore. Nessun dato nuovo.',ax:'Dzidzishvili, Ostojic, Chahla, LaPrade; Barcellona, Zagabria, Chicago, Edina',date:'nov 2026',meta:'editoriale, livello basso, solo abstract',pmid:'43012751',doi:'10.1002/ksa.70676',journal:'Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA',authors:'Lika Dzidzishvili, Marko Ostojic, Jorge Chahla, Robert F LaPrade',design:'Editoriale critico sulle prove della centralizzazione meniscale dopo riparazione della radice posteriore mediale; nessuna raccolta di dati.',pop:'Nessuna popolazione: commento sulla letteratura biomeccanica e clinica della centralizzazione.',results:'Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract (editoriale). Tesi: la centralizzazione riduce l\'estrusione e migliora la meccanica di contatto e gli esiti a breve, ma molti pazienti con artrosi preesistente ed estrusione persistente mantengono buoni risultati clinici nonostante la progressione radiografica.',concl:'Gli autori: nel ginocchio di mezza età, degenerativo, l\'estrusione potrebbe essere meno un motore della degenerazione che una manifestazione dell\'artrosi; resta da stabilire se l\'estrusione residua sia un bersaglio modificabile.',limits:'Opinione, non prova · Firmato da due autori del consensus Delphi sulla centralizzazione del 7 novembre · Nessun confronto clinico nuovo',perte:'Verde: tocca la tua rifissazione transtibiale della radice e la tensione sull\'estrusione. Interessante perché viene da chi la centralizzazione la promuove: alza il dubbio invece di chiuderlo. Cosa fare: nessun cambio; nel ginocchio già artrosico non aggiungere la centralizzazione sulla sola base dell\'estrusione residua.'},
{n:4,mono:'m-arth',dot:'green',sec:'res',j:'Arthroscopy',h:'Strumenti cannulati mal sterilizzati: dietro a gruppi di infezioni dopo LCA e artroscopia',v:'Revisione sistematica (Lubowitz): 14 lavori, 6 di laboratorio e 8 clinici; tutti i clinici sono serie di casi con cluster di infezioni, 6 dopo ricostruzione del LCA. Il lume degli strumenti cannulati trattiene spesso microrganismi e proteine anche dopo il ciclo standard.',ax:'Lubowitz; New Mexico Knee Surgery, Santa Fe',date:'nov 2026',meta:'revisione sistematica di serie di casi e studi di laboratorio, livello basso, solo abstract',pmid:'43010695',doi:'10.1002/arj.70714',journal:'Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association',authors:'James H Lubowitz',design:'Revisione sistematica PRISMA su PubMed, Lens, Google Scholar ed Embase, ricerca «sterilization cannulated surgical instruments»; inclusi studi clinici e di laboratorio su strumenti ortopedici cannulati; sintesi narrativa.',pop:'193 record, 12 inclusi più 2 dalle bibliografie: 6 studi di laboratorio su lavaggio e autoclave, 8 serie cliniche (1 artroscopia di ginocchio o spalla, 1 sutura meniscale inside-out, 6 ricostruzioni del LCA), tutte con indagine epidemiologica.',results:'Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract. Numero di infezioni e di pazienti delle serie cliniche: non riportato. Contaminazione del lume dimostrata di frequente negli studi di laboratorio (batteri, lieviti, muffe, proteine compresi i prioni).',concl:'Gli autori: il lume contaminato di strumenti ritenuti sterili può associarsi a cluster di infezioni dopo artroscopia; servono protocolli di pulizia e sterilizzazione rafforzati.',limits:'Serie di casi raccolte perché c\'era un cluster: dicono che può succedere, non quanto spesso · Autore unico · Nessuna stima di incidenza né confronto fra protocolli',perte:'Verde: tocca ogni tuo LCA e ogni sutura meniscale, cioè gli strumenti cannulati che usi di più. Non sposta la tecnica, sposta la filiera. Cosa fare: chiedi alla sterilizzazione della tua clinica come vengono spazzolati e lavati i lumi delle guide e dei prelevatori prima dell\'autoclave.'},
{n:5,mono:'m-gray',dot:'green',sec:'res',j:'Acta Ortop Bras',h:'Protesi totale: infiltrazione locale e blocco femorale danno lo stesso dolore, l\'infiltrazione muove meglio',v:'Meta-analisi di 11 RCT, 1.109 pazienti (Helito tra gli autori): dolore precoce MD 0,25 (IC 95% da −0,19 a 0,69) e oppioidi senza differenza; flessione in seconda giornata migliore con l\'infiltrazione di circa 6° e degenza più breve di circa un quarto di giornata.',ax:'Oliveira, Conde, Machinski, da Cruz, Helito, da Silva, Leal; San Paolo e Buenos Aires',date:'nov 2026',meta:'meta-analisi di RCT, 1.109 pazienti, livello alto, solo abstract',pmid:'43011475',doi:'10.1590/1413-785220263406e309147',journal:'Acta ortopedica brasileira',authors:'Andre Richard da Silva Oliveira, Rodrigo Bernstein Conde, Elcio Machinski, Vinicius Furtado da Cruz, Camilo Partezani Helito, Andre Giardino Moreira da Silva, Daniel Peixoto Leal',design:'Revisione sistematica e meta-analisi di RCT (Medline, Cochrane, Embase) che confrontano blocco femorale a iniezione singola e infiltrazione locale (LIA) nella protesi totale. Esiti: dolore, consumo di oppioidi, mobilità, degenza. Rischio di bias e certezza delle prove: non riportati nell\'abstract.',pop:'11 RCT, 1.109 pazienti operati di protesi totale di ginocchio; caratteristiche dei pazienti e composizione della miscela LIA: non riportate nell\'abstract.',results:'Dolore precoce MD 0,25 punti (IC 95% da −0,19 a 0,69); oppioidi MD 0,55 mg (da −3,28 a 4,38). Mobilità in seconda giornata MD −6,15° (da −9,16 a −3,14) a favore della LIA; degenza MD 0,23 giorni (da 0,06 a 0,41) più breve con la LIA.',concl:'Gli autori: la LIA si associa a migliore mobilità in seconda giornata e a degenza più breve, senza differenze di dolore o di oppioidi rispetto al blocco femorale singolo.',limits:'Confronto con il blocco femorale, oggi spesso sostituito dal blocco del canale degli adduttori · Differenze piccole: 6° e un quarto di giornata · Rischio di bias, eterogeneità e certezza non nell\'abstract',perte:'Verde: tocca l\'analgesia delle tue protesi; la decide anche l\'anestesista. Il dato conferma la direzione già presa ovunque: risparmiare il quadricipite. Cosa fare: nessun cambio se usi già infiltrazione o blocco degli adduttori; se il tuo percorso usa ancora il blocco femorale, è un argomento concreto per discuterlo.'},
{n:6,mono:'m-gray',dot:'green',sec:'res',j:'J Arthroplasty',h:'Cinque percorsi di protesi a confronto: differenze nel Forgotten Joint Score, ma non attribuibili all\'allineamento',v:'Coorte retrospettiva (UC Davis): 1.239 protesi in cinque percorsi, ognuno di un solo chirurgo. FJS-12 corretto da 39,7 a 58,0 (p = 0,004); solo il cinematico ristretto robotico supera il meccanico navigato bilanciato sugli spazi, di 18,2 punti (IC 95% 8,4-28,1). Soglie di beneficio raggiunte in modo simile.',ax:'Lum, Tse, Lee, Giordani, Meehan; UC Davis, Sacramento',date:'nov 2026',meta:'coorte retrospettiva comparativa, 1.239 protesi, livello medio, solo abstract',pmid:'43014558',doi:'10.1016/j.arth.2026.11.001',journal:'The Journal of arthroplasty',authors:'Zachary C Lum, Shannon Tse, Preston Lee, Mauro Giordani, John P Meehan',design:'Coorte retrospettiva da una banca dati istituzionale di esiti riferiti, cinque percorsi: navigato a resezione misurata meccanico, navigato bilanciato sugli spazi meccanico (postero-stabilizzati), robotico funzionale, robotico cinematico non ristretto, robotico cinematico ristretto (a conservazione del crociato). Esito primario FJS-12 a un anno, analisi multivariata corretta per il punteggio di partenza.',pop:'1.239 protesi totali: 394, 365, 246, 113 e 121 per percorso; ogni percorso corrisponde a un chirurgo. Età, sesso e IMC: non disponibili per gli autori.',results:'FJS-12 corretto da 39,7 a 58,0 fra i percorsi (p = 0,004); dopo correzione di Holm, solo cinematico ristretto contro meccanico bilanciato: +18,2 punti (IC 95% 8,4-28,1; p = 0,003), sopra la MCID di 16,6 ma con intervallo che include valori minori. KOOS JR p = 0,022 senza contrasti a coppie; PROMIS e VR-12 senza differenze; PASS dell\'FJS-12 72,8-82,9% (p = 0,902).',concl:'Gli autori: ogni percorso unisce chirurgo, piattaforma, impianto e filosofia, e mancano le covariate demografiche; le differenze non si possono attribuire alla strategia di allineamento.',limits:'Chirurgo, impianto e allineamento confusi del tutto: un percorso = un chirurgo · Nessuna covariata demografica · Piattaforme robotiche non specificate nell\'abstract',perte:'Verde: tocca il VELYS e la scelta dell\'allineamento. Il messaggio utile è metodologico: l\'onestà degli autori nel dire che il loro dato non distingue la filosofia dal chirurgo. Cosa fare: nessun cambio; non usare questo lavoro come prova per l\'allineamento cinematico.'},
{n:7,mono:'m-gray',dot:'green',sec:'res',j:'Arthroplasty',h:'Monocompartimentale robotica: chi parte con salute mentale bassa è meno soddisfatto a 6 mesi, non a 2 anni',v:'Registro prospettico (Singapore General Hospital): 121 su 241 monocompartimentali mediali robotiche con dati completi. Soddisfazione a 6 mesi 82,4% contro 97,1% (p = 0,008), nessuna differenza a 2 anni; miglioramenti del ginocchio simili, SF-36 fisico Δ 17,0 contro 11,1 (p = 0,006).',ax:'Ng, Lim, Chan, Goh, Tay, Pang, Yeo, Liow; Singapore',date:'nov 2026',meta:'coorte da registro prospettico, 121 pazienti, livello medio, solo abstract',pmid:'43010060',doi:'10.1186/s42836-026-00448-w',journal:'Arthroplasty (London, England)',authors:'Yong Ng, Jeremy Tze En Lim, Isaac Chan, Elliot Jun Wei Goh, Darren Keng Jin Tay, Hee Nee Pang, Seng-Jin Yeo, Ming Han Lincoln Liow',design:'Analisi di un registro raccolto prospetticamente, protesi monocompartimentali mediali robotiche consecutive 2017-2024; gruppi per SF-36 MCS preoperatorio (< 50 contro ≥ 50); esiti a 6 mesi e 2 anni; regressione logistica multivariata.',pop:'241 operati, 121 nel campione a dati completi: 51 con MCS < 50 (media 41,2) e 70 con MCS ≥ 50 (media 58,2). Piattaforma robotica: non riportata nell\'abstract.',results:'Miglioramenti di KSFS, KSKS e OKS simili fra i gruppi. SF-36 fisico a 2 anni Δ 17,0 contro 11,1 (p = 0,006), MCID 85,7% contro 66,7% (p = 0,024). A 6 mesi soddisfazione 82,4% contro 97,1% (p = 0,008) e aspettative soddisfatte 70,6% contro 90,0% (p = 0,008); a 2 anni nessuna differenza. MCS preoperatorio OR 1,078 per punto sulla soddisfazione a 6 mesi (p = 0,005).',concl:'Gli autori: una salute mentale preoperatoria bassa non dovrebbe escludere dalla monocompartimentale i pazienti ben selezionati; l\'MCS a 6 mesi è un segnale esplorativo per seguire più da vicino.',limits:'Metà degli operati (120 su 241) fuori dall\'analisi a dati completi: rischio di selezione · Soglia MCS ≥ 53 derivata internamente, non validata · Un solo centro, nessun confronto con la protesi totale',perte:'Verde: tocca le tue monocompartimentali. Il dato pratico è il calendario dell\'insoddisfazione: chi parte ansioso o depresso è più scontento a sei mesi, poi si allinea. Cosa fare: nel colloquio preoperatorio di questi pazienti anticipa che i primi mesi possono deludere.'},
{n:8,mono:'m-gray',dot:'gray',sec:'res',j:'J Arthroplasty',h:'Canada: la protesi totale non cementata raddoppia in cinque anni, trainata da un solo sistema',v:'Registro nazionale canadese, 218.229 protesi primarie 2019-2023: non cementate dall\'8,4% al 18,6%, oltre il 90% con un unico sistema d\'impianto. Uomini con più probabilità di riceverla (OR 1,59; IC 95% 1,55-1,63). Dato di adozione, non di esito.',ax:'Laende, Loughlin; University of Waterloo',date:'nov 2026',meta:'studio di registro nazionale, 218.229 protesi, livello medio, solo abstract',pmid:'43014559',doi:'10.1016/j.arth.2026.11.049',journal:'The Journal of arthroplasty',authors:'Elise K Laende, Naomi Loughlin',design:'Coorte retrospettiva dal Canadian Joint Replacement Registry, protesi totali primarie 2019-2023 in adulti; esito: fissazione cementata o non cementata; test di tendenza e regressione logistica corretta per età, sesso, anno e provincia; confronto con altri registri nazionali.',pop:'218.229 protesi totali primarie, di cui 14,3% non cementate.',results:'Quota non cementata dall\'8,4% (2019) al 18,6% (2023); un solo sistema d\'impianto oltre il 90% delle non cementate. Uomini OR 1,59 (IC 95% 1,55-1,63; p < 0,001); forte variazione fra province. Sopravvivenza e revisioni: non riportate (non era l\'obiettivo).',concl:'Gli autori: l\'uso della protesi non cementata in Canada è aumentato in modo marcato, soprattutto per la diffusione di un singolo sistema, nei più giovani e negli uomini.',limits:'Nessun esito: dice chi la riceve, non come va · Il sistema dominante non è nominato nell\'abstract · Possibile effetto di mercato più che di prove',perte:'Bianco: non cambia una tua decisione oggi, ma descrive dove va il mercato nordamericano. Utile quando un paziente o un rappresentante propone il non cementato come «più moderno»: questo registro misura la diffusione, non il beneficio.'}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Giovedì dodici novembre, otto lavori, nessuna scheda rossa, una arancione. Nessun richiamo di dispositivi nuovo che ti riguardi, nessuna ritrattazione di lavori che abbiamo citato e nessun citante nuovo sui tuoi verdetti passati; il raccoglitore è quello di ieri mattina e tutte le fonti hanno risposto. L'arancione tocca il tuo innesto nell'adolescente: alla Johns Hopkins, centocinquantaquattro ricostruzioni sotto i diciotto anni senza tenodesi laterale, artrofibrosi nel sette per cento con il quadricipite e in nessun caso con gli ischiocrurali. Ma gli eventi sono cinque, il rischio relativo resta indeterminato, e il quadricipite era scelto nei ginocchi con più lesioni condrali. Il quattro novembre l'UCLA dava la colpa alla tenodesi e non all'innesto: due coorti piccole, due colpevoli diversi. Per te: controlla l'estensione presto, a quattro-sei settimane. Il lavoro del giorno è il trial PEPPER sul New England: oltre quindicimila protesi d'anca e di ginocchio, aspirina, warfarin o rivaroxaban per trenta giorni. Morte o trombosi sintomatica a sei mesi, uno virgola ventisei per cento con aspirina contro zero virgola novantaquattro con rivaroxaban: l'aspirina non si dimostra non inferiore. Sulla sicurezza l'aspirina va un po' meglio, senza significatività. Nessun braccio vince: è uno scambio, e il ginocchio da solo non è nel riassunto. Se usi un anticoagulante, nessun motivo di cambiare. Terza scheda, un editoriale di Chahla e LaPrade: l'estrusione meniscale potrebbe essere conseguenza dell'artrosi più che causa, un dubbio che viene da chi la centralizzazione la promuove. Quarta, Lubowitz su Arthroscopy: gli strumenti cannulati mal puliti sono dietro a gruppi di infezioni dopo crociato; vale una domanda alla tua sterilizzazione. Quinta, una meta-analisi con Helito: l'infiltrazione locale controlla il dolore come il blocco femorale e fa piegare meglio il ginocchio in seconda giornata. Sesta, a Davis cinque percorsi di protesi danno Forgotten Joint Score diversi, ma ogni percorso è un chirurgo, quindi l'allineamento non si isola. Settima, a Singapore la monocompartimentale robotica: chi parte con salute mentale bassa è meno soddisfatto a sei mesi, non a due anni. Ottava, il registro canadese: le protesi non cementate raddoppiano in cinque anni, trainate da un solo sistema, senza dati di esito. Nessuna tensione chiusa; la prima, sul LET e il tuo innesto, riceve il dato pediatrico di oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Giovedì dodici novembre, otto lavori, nessuna scheda rossa e una arancione. Nessun richiamo nuovo che ti riguardi, nessuna ritrattazione e nessun citante nuovo sui tuoi verdetti."}, {"chi": "B", "t": "Partiamo dall'arancione. Che cosa tocca?"}, {"chi": "A", "t": "Il tuo innesto nell'adolescente. Alla Johns Hopkins, centocinquantaquattro ricostruzioni sotto i diciotto anni senza tenodesi laterale: artrofibrosi nel sette per cento con il quadricipite, in nessun caso con gli ischiocrurali."}, {"chi": "B", "t": "Quindi il quadricipite irrigidisce i ragazzi?"}, {"chi": "A", "t": "Non si può dire così. Gli eventi sono cinque, il rischio relativo resta indeterminato, e il quadricipite era scelto nei ginocchi con più lesioni condrali. Il quattro novembre l'UCLA dava la colpa alla tenodesi, non all'innesto."}, {"chi": "B", "t": "Allora per i suoi adolescenti con quadricipite e LET, cosa cambia in pratica?"}, {"chi": "A", "t": "Controllare l'estensione presto, a quattro-sei settimane, invece di aspettare i tre mesi."}, {"chi": "B", "t": "Il lavoro del giorno?"}, {"chi": "A", "t": "Il trial PEPPER sul New England, oltre quindicimila protesi: aspirina, warfarin o rivaroxaban per trenta giorni. Morte o trombosi a sei mesi, uno virgola ventisei per cento con aspirina contro zero virgola novantaquattro con rivaroxaban: l'aspirina non si dimostra non inferiore."}, {"chi": "B", "t": "Quindi rivaroxaban per tutti?"}, {"chi": "A", "t": "No. Sulla sicurezza l'aspirina va un po' meglio, senza significatività, e nessun braccio è superiore. È uno scambio, e il ginocchio da solo non è nel riassunto. Se usi un anticoagulante, nessun motivo di cambiare."}, {"chi": "B", "t": "E il menisco?"}, {"chi": "A", "t": "Un editoriale di Chahla e LaPrade: l'estrusione potrebbe essere conseguenza dell'artrosi più che causa. Niente dati nuovi, ma il dubbio viene da chi la centralizzazione la promuove."}, {"chi": "B", "t": "Qualcosa da fare già domani?"}, {"chi": "A", "t": "Una domanda alla sterilizzazione: Lubowitz collega gli strumenti cannulati mal puliti a gruppi di infezioni dopo crociato. Poi, sulle protesi, l'infiltrazione locale vale il blocco femorale sul dolore e fa piegare meglio in seconda giornata."}, {"chi": "B", "t": "E il robot?"}, {"chi": "A", "t": "Due lavori: a Davis i percorsi di protesi danno risultati diversi ma ogni percorso è un chirurgo, quindi l'allineamento non si isola; a Singapore, nella monocompartimentale, chi parte con salute mentale bassa è meno soddisfatto a sei mesi ma non a due anni. In coda il registro canadese: le non cementate raddoppiano, senza dati di esito."}];
